"""English public report, generated only from synthetic/public test receipts."""
import datetime,html,json,statistics
from pathlib import Path
from final_verify import runtime_signature

ROOT=Path(__file__).parent
def read(name):
    path=ROOT/name;return json.loads(path.read_text()) if path.exists() else {}

def main():
    browser=read('logs/multimodal-browser-checks.json');live=read('logs/multimodal-live-checks.json');unit=read('logs/unit-checks.json')
    gaze=read('logs/gaze-rendering-checks.json');ui=read('logs/browser-ui-status.json');assets=read('static/deps/assets-manifest.json')
    signature=runtime_signature();live_ok=bool(live.get('passed') and live.get('runtime_source_sha256')==signature and len(live.get('cases',[]))>=8)
    models=browser.get('real_models',{});landmark=models.get('landmark_ms',[]);embedding=[p['ms'] for p in models.get('embedding',[])]
    e=lambda value:html.escape(str(value))
    status=lambda value:'PASS' if value else 'NOT VERIFIED / PENDING'
    rows=[('Browser settings, consent and CPU models',status(browser.get('passed')),'Real Chromium over HTTPS; fake capture device, synthetic behavioral landmarks and public NASA image, no physical users'),
        ('Live multimodal response gate + greetings',status(live_ok),'Real ASR, acoustic enrollment and shared streaming TTS; timestamped synthetic visual activity; current source hash required'),
        ('Offline contracts',status(unit.get('passed')),str(unit.get('tests',0))+' tests, including time alignment, overlap, fallback, introductions and cooldowns'),
        ('Prior UI and gaze/calibration regression',status(ui.get('passed') and gaze.get('passed')),'Existing 0.32 voice threshold, keyboard tour, numeric calibration and manual stop controls preserved'),
        ('Two-face CPU landmarks, warm median',f'{statistics.median(landmark[1:]):.1f} ms' if len(landmark)>1 else 'pending','One CPU/WASM worker; configured camera maximum 10 FPS; no inference queue'),
        ('128-D Face-ID, warm median',f'{statistics.median(embedding[1:]):.1f} ms' if len(embedding)>1 else 'pending','Separate CPU JavaScript worker; lazy, not each video frame; model load/download excluded'),
        ('Two-face temporal tracking/mouth bookkeeping',f"{browser.get('geometry',{}).get('geometry_two_faces_ms',0):.3f} ms/frame",'Synthetic 1,000-frame benchmark; separate from neural landmark inference'),
        ('Local browser dependencies',f'{sum(a.get("bytes",0) for a in assets)/1e6:.1f} MB' if isinstance(assets,list) else 'pending','Bounded versioned libraries, CPU WASM and model files; no additional server GPU model'),
        ('Physical room recognition accuracy','NOT MEASURED','No claim of human face/speaker accuracy, liveness or physical A/V synchronization accuracy')]
    out='''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Robby · Multimodal speakers</title><style>body{font:16px/1.6 system-ui;background:#f8f7f3;color:#26343c;max-width:1120px;margin:auto;padding:24px}h1,h2{line-height:1.2}table{border-collapse:collapse;background:white;width:100%}td,th{border:1px solid #ddd;padding:10px;text-align:left;vertical-align:top}.scroll{overflow:auto}section{background:white;border-radius:16px;padding:18px;margin:20px 0}code,pre{overflow-wrap:anywhere;white-space:pre-wrap}a{color:#306a74}</style><nav><a href="/desk-robot/">Open 3D Robby</a> · <a href="/static/worklog.html">Full task log</a> · <a href="/downloads/robby-source.zip">Reproducible source</a></nav><h1>Additive multimodal people recognition</h1>'''
    out+='<p>Updated '+e(datetime.datetime.now(datetime.timezone.utc).isoformat())+'. Experimental assistance, not secure biometric authentication. Existing audio/turn-taking remains authoritative. <a href="/static/reliability-update.html">New camera defaults, people gallery and interruption reliability update</a>.</p><div class="scroll"><table><tr><th>Finding</th><th>Result</th><th>Meaning / measurement scope</th></tr>'
    for row in rows:out+='<tr>'+''.join('<td>'+e(v)+'</td>' for v in row)+'</tr>'
    out+='</table></div><section><h2>How to use it</h2><ol><li>Turn Camera on and Start talking. Introduce yourself: “Hey Robby, ich bin Bob” or “Hi Robby, my name is Alice”.</li><li>Keep one clearly speaking face visible during introduction. The verified voice and face receive a common person ID only when the visual match is unambiguous.</li><li>The three visible-speaker checkboxes are independently enabled by default and remembered in this browser.</li><li>Camera off/unavailable deliberately falls back to the previous audio-only behavior. Camera ON with no visible speaking person or ambiguous overlap abstains. Turn Ignore offscreen speakers off to retain audio-only eligibility with the camera on.</li><li>Face and voice profiles are session-only unless EVERY affected person has explicitly consented to storage. Remember prompts for confirmation; withdrawal removes saved profiles. Forget all clears both browser and active server speaker memory.</li></ol></section>'
    out+='<section><h2>Architecture and models</h2><p>Existing webcam → MediaPipe Face Landmarker 0.10.21 CPU/WASM worker → stable bounding-box tracks and normalized lip/jaw motion over 700 ms → microphone-sample-clock matching → existing acoustic gate → unchanged Luna and shared Humaneness speech model. Audio-correlated speaker position feeds the existing smoothed gaze controller. Face descriptors use a second lazy worker with only face-api.js 0.22.2 recognition net (128 dimensions; 6,444,032 bytes of weight shards). No second camera, face detector, landmark model, age/gender model or server GPU pipeline is added.</p><p>Time-varying normalized lip distances must change direction repeatedly; a static open mouth, closed mouth and rigid translation/scale fail the activity tests. Confidence hysteresis, 380-ms minimum observation span, brief-loss grace, crossing ambiguity and gaze-switch dwell reduce jitter. Face descriptor Euclidean distance &lt;0.48 and runner-up gap &gt;0.08 are development thresholds, not probability estimates.</p><p>Human was inspected, including its model catalog and descriptor code; the standalone face-api recognition API was simpler to isolate without attribute inference. This is not a benchmark proving superiority to every Human variant. VSDLM and ONNX Runtime were reviewed but not added: another mouth-state classifier is not needed for the current landmark-first implementation. Comparative VSDLM/real-room accuracy remains unmeasured.</p></section>'
    out+='<section><h2>Live conditions</h2><table><tr><th>Condition</th><th>Result</th><th>Endpoint</th><th>Audio bytes received</th></tr>'
    for case in live.get('cases',[]):out+='<tr>'+''.join('<td>'+e(v)+'</td>' for v in (case.get('mode'),status(case.get('passed')),case.get('endpoint'),case.get('streamed_audio_bytes','—')))+'</tr>'
    out+='</table><p>Visual observations in this test are synthetic. They exercise the actual WebSocket gate while Nemotron, the speaker models and TTS run normally. Browser tests separately exercise real face models. These are complementary integration checks, not a recorded multi-person human conversation.</p><p>The first run correctly gated visible/offscreen/static/overlap conditions but hit an existing intermittent Luna provider HTTP 400 on the disabled-filter reply. A five-request public-prompt diagnostic reproduced one transient client_side_error followed by four successful identical calls. The director now retries that exact rejection once; arbitrary 400s, schema errors, authentication and safety failures are not retried. Old failures remain in local receipts and are not counted as passes.</p></section>'
    out+='<section><h2>Privacy, limits and remaining validation</h2><p>Face images, landmarks and descriptors stay in browser memory. The server receives bounded temporary track IDs, activity scores and capture times, not images. The visible people gallery shows the original enrollment crop separately from the current camera crop; old profiles with no photo explicitly say so. Consented name/face/audio profiles are stored unencrypted on this device only; default persistence is OFF. A new person pauses saving until consent is renewed. No private microphone/camera material or enrolled voiceprints is published.</p><p>Up to four visible faces and eight enrolled people are supported. Chewing, repeated non-speech mouth motion, occlusion, poor light, tiny/sideways faces, crossed tracks and overlapping speech can be uncertain; the system abstains rather than enforcing an identity. Merely seeing a known face does not authorize audio: the separate corroborated interjection route still needs teacher, fast and long evidence. Gaze calibration remains perceptual, not a camera geometry calibration. Webcam input latency may be incompletely reported; ±160 ms is a matching tolerance, not physically measured synchronization accuracy. Camera-unavailable fallback is explicitly displayed.</p><p>Historical short-word interruption identity and arbitrary semantic interruption rules still have retained failure cases in the full worklog. Passing this multimodal test does not turn those older open research items into verified successes.</p></section>'
    out+='<section><h2>Changed files and reproduction</h2><p>Core additions: <code>visual_identity.py; static/visual-speakers.js; static/multimodal-ui.js; static/face-camera-worker.js; static/face-id-worker.js</code>. Additive wiring: <code>server.py; speaker_session.py; static/client.js; static/ui.js; live_decisions.py</code>. Assets and QA: <code>bootstrap_visual_assets.py; browser_multimodal_checks.py; static/multimodal-test-cases.js; multimodal_live_checks.py; test_visual_identity.py; run_unit_checks.py</code>. Existing gaze/camera harnesses were adapted to worker inference; <code>conversation_director.py</code> adds the tightly scoped provider retry and its unit test. Documentation/source integrity: README, NOTICE, final_verify, build_worklog and this report generator.</p><pre>python bootstrap_visual_assets.py\npython run_unit_checks.py\nuv run --no-project --with playwright --python /path/to/python browser_multimodal_checks.py\npython multimodal_live_checks.py\npython build_multimodal_report.py</pre><p>Dependencies are excluded from the text-only source ZIP; bootstrap restores the pinned files and records hashes. All timing figures are measured on this host’s headless Chromium with GPU rendering disabled, not a promise for every user CPU.</p></section>'
    out+='<p>Primary sources: <a href="https://developers.google.com/edge/mediapipe/solutions/vision/face_landmarker/web_js">MediaPipe Web</a> · <a href="https://github.com/justadudewhohacks/face-api.js/tree/8609b25a15f417398a4d2b95dc91985cd1e0c0c3">Pinned face-api.js</a> · <a href="https://github.com/vladmandic/human/wiki/Models">Human models</a> · <a href="https://github.com/PINTO0309/VSDLM">VSDLM</a>.</p><details><summary>Test scope and source integrity</summary><pre>'+e(json.dumps({'runtime_source_sha256':signature,'live_source_matches':live.get('runtime_source_sha256')==signature,'live_current_eight_cases_pass':live_ok,'physical_devices_used':False,'browser_cases':browser.get('cases',[])},indent=2))+'</pre></details></html>'
    (ROOT/'static/multimodal-report.html').write_text(out)
    print(json.dumps({'browser_passed':browser.get('passed'),'current_live_eight_passed':live_ok,'report':'static/multimodal-report.html'}))

if __name__=='__main__':main()
